    home: {"heroEyebrow": "Pré-lancement • Pour les églises du monde entier", "heroTitle": "Garder le regard sur Christ.", "heroSub": "Coupes de Sainte Cène simples, hygiéniques et économiques, conçues pour les églises. Pain et jus scellés ensemble — prêts à être distribués en quelques secondes.", "heroCta": "Demander les prix", "heroStat1Value": "100%", "heroStat1Label": "Fabriqué en Italie", "heroStat2Value": "12 mois", "heroStat2Label": "Conservation", "heroStat3Value": "6+", "heroStat3Label": "Pays desservis", "trust": ["Fabriqué en Italie", "Expédition rapide en Europe", "Soutient la mission", "Conçu pour les églises"], "whyEyebrow": "LA VRAIE SAINTE CÈNE", "whyTitle": "La Sainte Cène devrait nous unir — pas nous distraire.", "whyProblemsTitle": "Défis communs pendant la Sainte Cène", "whyIntro": "La préparation et la distribution traditionnelles introduisent souvent du bruit, des mouvements et des retards précisément au moment où la communauté a le plus besoin de silence.", "problems": [{"t": "", "d": "Les mouvements, les chuchotements et les pas détournent l'attention de Christ."}], "solution": {"title": "Une coupe scellée. Pain et jus, prêts.", "body": "Chaque coupe pré-remplie contient le pain et le jus, ensemble, scellés. Pas de distribution ni de bruit pendant le moment sacré — seulement un silence respectueux sur chaque banc."}, "benefitsEyebrow": "Avantages", "benefitsTitle": "Tout ce dont votre église a besoin — rien de superflu.", "benefitsSub": "Conçu avec des pasteurs et des administrateurs, perfectionné par une véritable utilisation dominicale.", "benefits": [{"t": "Pain et jus ensemble", "d": "Une coupe, un geste."}, {"t": "Ouverture simple", "d": "Deux opercules détachables. Tout le monde peut l'ouvrir d'un geste doux."}, {"t": "Distribution rapide", "d": "Servez des centaines de personnes en quelques minutes, sans files d'attente."}, {"t": "Hygiène garantie", "d": "Chaque portion est individuelle, sûre et sans contamination."}, {"t": "Silence respecté", "d": "Un culte plus silencieux, plus de place à la réflexion."}, {"t": "Zéro distraction", "d": "L'attention reste là où elle devrait être — sur Christ."}], "pricingEyebrow": "PRIX", "pricingTitle": "Des prix pour les églises, honnêtes et clairs.", "pricingSub": "Une comparaison entre les prix typiques du marché et nos prix de lancement attendus. Les devis finaux dépendent du volume et du pays.", "pricingHeaderQty": "Boîte", "pricingHeaderMarket": "Prix du marché", "pricingHeaderOurs": "Notre prix", "pricingHeaderSave": "Économies", "pricingCta": "Demander un devis", "pricingDisclaimer": "Le prix final dépend du volume de la commande, du pays de destination et des spécifications.", "impactEyebrow": "Notre Mission", "impactTitle": "Plus que de simples coupes. Une vision pour l'avenir.", "impactSubhead": "Notre désir n'est pas seulement de servir les églises en rendant la Sainte Cène plus accessible, mais aussi d'utiliser la croissance de cette entreprise pour soutenir la mission chrétienne et apporter de l'espoir aux communautés du monde entier.", "impactBody": "Nous croyons qu'aucune église ne devrait avoir à choisir entre la qualité et l'abordabilité. Qu'elle soit petite ou grande, en Europe ou ailleurs, chaque congrégation mérite une solution pour la Sainte Cène qui garde l'attention sur Christ. Et au fur et à mesure que The Holy Supper grandit, notre espoir est que chaque coupe fasse partie de quelque chose de plus grand.", "impactPillars": [{"t": "", "d": "Aux côtés des pasteurs et des communautés partout où ils servent."}, {"t": "", "d": "Une aide pratique là où l'espoir est le plus nécessaire."}, {"t": "", "d": "Investir dans les salles de classe pour élever une nouvelle génération."}, {"t": "", "d": "Soutenir les puits et l'eau potable là où la vie quotidienne en dépend."}], "impactCaption": "Une vision au-delà de l'église locale", "impactClosing": "Domaines dans lesquels nous espérons investir à mesure que nous grandissons", "impactFooter1": "L'Ouganda est l'un des endroits qui a inspiré cette vision — une image de l'impact que nous souhaitons étendre à de nombreux pays à mesure que l'entreprise grandit.", "impactFooter2": "Notre prière est que chaque coupe que nous fournissons puisse un jour aider à fortifier les églises locales et créer des opportunités pour servir des personnes au-delà d'elles.", "howEyebrow": "Comment ça marche", "howTitle": "Du premier message à votre église, en quatre étapes.", "howSteps": [{"t": "Remplissez le formulaire", "d": "Dites-nous ce dont votre église a besoin."}, {"t": "Recevez le prix", "d": "Un devis sur mesure pour votre pays."}, {"t": "Nous produisons", "d": "Coupes fabriquées en Italie, pour vous."}, {"t": "Nous expédions", "d": "Expédié en toute sécurité à votre porte."}], "faqEyebrow": "FAQ", "faqTitle": "Des réponses pour les pasteurs, les administrateurs et les responsables de ministère.", "finalCtaEyebrow": "Pré-lancement", "finalCtaTitle": "Soyez parmi les premières églises à recevoir nos prix de lancement.", "finalCtaButton": "Demander les prix"},
